"use client";

import { useMemo, useRef, useState, type Dispatch, type SetStateAction } from "react";
import Link from "next/link";
import {
  AlertTriangle, ArrowLeft, CalendarDays, Car, Check, ChevronDown, ChevronRight,
  CircleAlert, Clock3, Compass, Copy, ExternalLink, Footprints, Loader2, MapPin,
  Minus, Navigation, Plus, RefreshCw, Route, Send, ShieldCheck, Sparkles, Star,
  Train, UserRound, WalletCards,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { Sheet, SheetClose, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { RouteMapClient } from "@/components/route-map-client";
import { placeById } from "@/lib/nyc-places";
import { suggestReplacements } from "@/lib/nyc-planner";
import type { Itinerary, NycPlace, PlaceCategory, PlanMode, PlanRequest, TransportSegment } from "@/lib/nyc-types";

const initialRequest: PlanRequest = {
  cityCode: "nyc", date: "2026-10-10", duration: "half_day", durationHours: 6,
  partySize: 2, totalBudgetUsd: 220, interests: ["landmark", "architecture", "museum"],
  intentText: "", transportPreference: "smart", walkingPreference: "balanced",
  dining: "no_preference", accessibility: false,
};

const shortcuts: Array<{ label: string; category: PlaceCategory }> = [
  { label: "Landmarks", category: "landmark" }, { label: "Museums", category: "museum" },
  { label: "Architecture", category: "architecture" }, { label: "Parks", category: "park" },
  { label: "Waterfront", category: "waterfront" }, { label: "Food", category: "food" },
];

type Screen = "planner" | "loading" | "itinerary" | "adjust" | "changed" | "conflict" | "error" | "profile";
type SheetName = "city" | "preferences" | "detail" | "transport" | "handoff" | "feedback" | "auth" | null;
type PreferenceKey = "transport" | "walking" | "dining" | "accessibility";
type AdjustmentAction = "replace" | "shorten" | "budget";
type TransportMode = "walk" | "public_transit" | "taxi";
type PlanResponse = { itinerary?: Itinerary | null; mode?: PlanMode; insufficiencyReason?: string; error?: { message?: string } };

const preferences: Record<PreferenceKey, { title: string; options: Array<{ value: string; label: string; note?: string }> }> = {
  transport: { title: "Getting around", options: [
    { value: "smart", label: "Smart recommendation", note: "Use walking for short links and transit for longer ones." },
    { value: "public_transit", label: "Public transit" }, { value: "taxi", label: "Taxi preferred" }, { value: "walk", label: "Walk preferred" },
  ] },
  walking: { title: "Walking pace", options: [{ value: "easy", label: "Easy" }, { value: "balanced", label: "Balanced" }, { value: "active", label: "Active" }] },
  dining: { title: "Dining preference", options: [{ value: "no_preference", label: "No preference" }, { value: "vegetarian", label: "Vegetarian-friendly" }, { value: "coffee", label: "Coffee stop" }, { value: "local", label: "Local food" }] },
  accessibility: { title: "Accessibility", options: [{ value: "false", label: "No specific accessibility request" }, { value: "true", label: "Prioritize accessibility", note: "Confirm venue accessibility directly before travel." }] },
};

function formatDate(date: string) {
  const parsed = new Date(`${date}T12:00:00`);
  return Number.isNaN(parsed.getTime()) ? date : new Intl.DateTimeFormat("en-US", { month: "long", day: "numeric", weekday: "short" }).format(parsed);
}

function clampNumber(value: string, min: number, max: number, fallback: number) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.max(min, Math.min(max, Math.round(number))) : fallback;
}

function hoursFor(request: PlanRequest) { return request.durationHours ?? (request.duration === "full_day" ? 10 : 6); }
function transportLabel(mode: TransportMode) { return mode === "walk" ? "Walk" : mode === "public_transit" ? "Public transit" : "Taxi"; }
function TransportIcon({ mode, className }: { mode: TransportMode; className?: string }) { const Icon = mode === "walk" ? Footprints : mode === "public_transit" ? Train : Car; return <Icon className={className} />; }
function preferenceText(request: PlanRequest, key: PreferenceKey) {
  if (key === "transport") return { smart: "Smart recommendation", public_transit: "Public transit", taxi: "Taxi preferred", walk: "Walk preferred" }[request.transportPreference];
  if (key === "walking") return { easy: "Easy", balanced: "Balanced", active: "Active" }[request.walkingPreference];
  if (key === "dining") return { no_preference: "No preference", vegetarian: "Vegetarian-friendly", coffee: "Coffee stop", local: "Local food" }[request.dining];
  return request.accessibility ? "Prioritized" : "Not selected";
}

function AppHeader({ onProfile, onBack, title }: { onProfile?: () => void; onBack?: () => void; title?: string }) {
  return <header className="flex min-h-14 items-center justify-between px-5 py-3">
    {onBack ? <button type="button" onClick={onBack} aria-label="Go back" className="grid size-11 place-items-center rounded-full text-[#1e5738] hover:bg-[#edf6ef]"><ArrowLeft className="size-5" /></button> : <button type="button" className="text-[22px] font-bold tracking-[-0.55px] text-[#1e5738]">Wayly</button>}
    {title ? <p className="text-sm font-semibold text-[#1e2939]">{title}</p> : null}
    {onProfile ? <button type="button" onClick={onProfile} aria-label="Open profile" className="grid size-11 place-items-center rounded-full text-[#4a5565] hover:bg-[#f3f4f6]"><UserRound className="size-5" /></button> : <span className="size-11" />}
  </header>;
}

function BottomNav({ active, onHome, onProfile }: { active: "home" | "profile"; onHome: () => void; onProfile: () => void }) {
  return <nav aria-label="Primary navigation" className="fixed inset-x-0 bottom-0 z-30 border-t border-[#eef0ec] bg-white/95 pb-[max(8px,env(safe-area-inset-bottom))] pt-2 backdrop-blur"><div className="mx-auto grid max-w-[390px] grid-cols-2 px-12">
    <button type="button" onClick={onHome} className={`flex min-h-12 flex-col items-center justify-center gap-0.5 text-[11px] font-medium ${active === "home" ? "text-[#1e5738]" : "text-[#99a1af]"}`}><Compass className="size-[18px]" />Explore</button>
    <button type="button" onClick={onProfile} className={`flex min-h-12 flex-col items-center justify-center gap-0.5 text-[11px] font-medium ${active === "profile" ? "text-[#1e5738]" : "text-[#99a1af]"}`}><UserRound className="size-[18px]" />Profile</button>
  </div></nav>;
}

export default function Home() {
  const [screen, setScreen] = useState<Screen>("planner");
  const [request, setRequest] = useState<PlanRequest>(initialRequest);
  const [itinerary, setItinerary] = useState<Itinerary | null>(null);
  const [previousItinerary, setPreviousItinerary] = useState<Itinerary | null>(null);
  const [mode, setMode] = useState<PlanMode | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const [sheet, setSheet] = useState<SheetName>(null);
  const [preferenceKey, setPreferenceKey] = useState<PreferenceKey>("transport");
  const [detailPlace, setDetailPlace] = useState<NycPlace | null>(null);
  const [selectedSegment, setSelectedSegment] = useState<TransportSegment | null>(null);
  const [selectedTransport, setSelectedTransport] = useState<Record<string, TransportMode>>({});
  const [handoffProvider, setHandoffProvider] = useState<string | null>(null);
  const [adjustmentAction, setAdjustmentAction] = useState<AdjustmentAction>("replace");
  const [targetStopId, setTargetStopId] = useState<string | null>(null);
  const [candidateId, setCandidateId] = useState<string | null>(null);
  const [adjustmentBudget, setAdjustmentBudget] = useState(initialRequest.totalBudgetUsd);
  const [toast, setToast] = useState<string | null>(null);
  const [feedbackDraft, setFeedbackDraft] = useState({ satisfaction: 0, trust: 0, issueType: "", note: "" });
  const [feedbackSubmitting, setFeedbackSubmitting] = useState(false);
  const controllerRef = useRef<AbortController | null>(null);
  const plannedPlaces = useMemo(() => itinerary?.stops.map((stop) => placeById[stop.placeId]).filter((place): place is NycPlace => Boolean(place)) ?? [], [itinerary]);

  const showToast = (value: string) => { setToast(value); window.setTimeout(() => setToast((current) => current === value ? null : current), 3200); };
  const setDurationHours = (durationHours: number) => setRequest((current) => ({ ...current, durationHours, duration: durationHours > 7 ? "full_day" : "half_day" }));
  const generate = async (nextRequest = request, successScreen: "itinerary" | "changed" = "itinerary") => {
    controllerRef.current?.abort(); const controller = new AbortController(); controllerRef.current = controller; setMessage(null); setScreen("loading");
    try {
      const response = await fetch("/api/plan", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(nextRequest), signal: controller.signal });
      const payload = await response.json() as PlanResponse;
      if (controller.signal.aborted) return;
      if (!response.ok) throw new Error(payload.error?.message ?? "The planning service is temporarily unavailable.");
      if (payload.itinerary && payload.mode && payload.mode !== "insufficient_information") { setItinerary(payload.itinerary); setMode(payload.mode); setScreen(successScreen); return; }
      setMode("insufficient_information"); setMessage(payload.insufficiencyReason ?? "A reliable itinerary is not available for these constraints."); setScreen("conflict");
    } catch (error) { if (!controller.signal.aborted) { setMessage(error instanceof Error ? error.message : "The network is temporarily unavailable."); setScreen("error"); } }
    finally { if (controllerRef.current === controller) controllerRef.current = null; }
  };
  const openAdjustment = () => { if (itinerary) { setTargetStopId(itinerary.stops[0]?.id ?? null); setCandidateId(null); setAdjustmentBudget(request.totalBudgetUsd); setScreen("adjust"); } };
  const applyAdjustment = () => {
    if (!itinerary) return;
    const durationHours = adjustmentAction === "shorten" ? Math.max(1, hoursFor(request) - 2) : request.durationHours;
    const base: PlanRequest = { ...request, durationHours, duration: (durationHours ?? hoursFor(request)) > 7 ? "full_day" : "half_day", totalBudgetUsd: adjustmentAction === "budget" ? adjustmentBudget : request.totalBudgetUsd, adjustment: undefined };
    const next: PlanRequest = { ...base, adjustment: { action: adjustmentAction, itineraryId: itinerary.id, previousPlaceIds: itinerary.stops.map((stop) => stop.placeId), ...(adjustmentAction === "replace" && targetStopId ? { targetStopId } : {}), ...(adjustmentAction === "replace" && candidateId ? { replacementPlaceId: candidateId } : {}) } };
    setPreviousItinerary(itinerary); setRequest(base); void generate(next, "changed");
  };
  const submitFeedback = async () => {
    if (!itinerary || !feedbackDraft.satisfaction || !feedbackDraft.trust) { showToast("Complete both ratings before submitting."); return; }
    setFeedbackSubmitting(true);
    try {
      const response = await fetch("/api/feedback", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ itineraryId: itinerary.id, rating: feedbackDraft.satisfaction >= 4 ? "helpful" : "not_helpful", satisfactionScore: feedbackDraft.satisfaction, trustScore: feedbackDraft.trust, issueType: feedbackDraft.issueType || undefined, note: feedbackDraft.note || undefined, itineraryVersion: itinerary.version, dataVersionId: itinerary.dataVersionId }) });
      if (!response.ok) throw new Error(); setSheet(null); setFeedbackDraft({ satisfaction: 0, trust: 0, issueType: "", note: "" }); showToast("Thanks — your feedback was saved for this preview.");
    } catch { showToast("Feedback was not saved. Please try again later."); } finally { setFeedbackSubmitting(false); }
  };
  const copyHandoff = async () => {
    if (!selectedSegment || !itinerary) return;
    const from = itinerary.stops.find((stop) => stop.id === selectedSegment.fromStopId)?.name ?? "Start";
    const to = itinerary.stops.find((stop) => stop.id === selectedSegment.toStopId)?.name ?? "Destination";
    const text = `${from} to ${to} (${transportLabel(selectedTransport[selectedSegment.toStopId] ?? selectedSegment.recommendedMode)})`;
    try { await navigator.clipboard.writeText(text); showToast("Route endpoints copied."); } catch { showToast(text); }
  };

  return <main className="min-h-dvh bg-[#f7f8f5] text-[#1e2939]"><div className="mx-auto min-h-dvh max-w-[390px] bg-white shadow-[0_0_0_1px_rgba(30,87,56,0.04)]">
    {screen === "planner" && <PlannerScreen request={request} setRequest={setRequest} setDurationHours={setDurationHours} openCity={() => setSheet("city")} openPreference={(key) => { setPreferenceKey(key); setSheet("preferences"); }} onGenerate={() => void generate()} onProfile={() => setScreen("profile")} />}
    {screen === "loading" && <LoadingScreen request={request} onCancel={() => { controllerRef.current?.abort(); setScreen("planner"); showToast("Planning cancelled. Your inputs were kept."); }} />}
    {(screen === "itinerary" || screen === "changed") && itinerary && <ItineraryScreen itinerary={itinerary} previousItinerary={screen === "changed" ? previousItinerary : null} plannedPlaces={plannedPlaces} mode={mode} request={request} selectedTransport={selectedTransport} onBack={() => setScreen("planner")} onProfile={() => setScreen("profile")} onOpenDetail={(place) => { setDetailPlace(place); setSheet("detail"); }} onOpenTransport={(segment) => { setSelectedSegment(segment); setSheet("transport"); }} onAdjust={openAdjustment} onSave={() => setSheet("auth")} onFeedback={() => setSheet("feedback")} onHome={() => setScreen("planner")} onProfileNav={() => setScreen("profile")} onClearChange={() => { setPreviousItinerary(null); setScreen("itinerary"); }} showToast={showToast} />}
    {screen === "adjust" && itinerary && <AdjustmentScreen itinerary={itinerary} request={request} action={adjustmentAction} targetStopId={targetStopId} candidateId={candidateId} budget={adjustmentBudget} onBack={() => setScreen("itinerary")} onAction={setAdjustmentAction} onTarget={(value) => { setTargetStopId(value); setCandidateId(null); }} onCandidate={setCandidateId} onBudget={setAdjustmentBudget} onSubmit={applyAdjustment} />}
    {screen === "conflict" && <ConstraintScreen message={message ?? "These constraints cannot produce a reliable route."} request={request} onEdit={() => setScreen("planner")} onRelax={() => { setRequest((current) => ({ ...current, totalBudgetUsd: Math.min(10_000, current.totalBudgetUsd + 25), accessibility: false, dining: current.dining === "vegetarian" ? "no_preference" : current.dining })); setScreen("planner"); }} />}
    {screen === "error" && <ErrorScreen message={message ?? "The service is temporarily unavailable."} onRetry={() => void generate()} onEdit={() => setScreen("planner")} />}
    {screen === "profile" && <ProfileScreen itinerary={itinerary} onBack={() => setScreen("planner")} onSave={() => setSheet("auth")} onHome={() => setScreen("planner")} onProfile={() => setScreen("profile")} />}
  </div>
  <OverlaySheets sheet={sheet} setSheet={setSheet} request={request} setRequest={setRequest} preferenceKey={preferenceKey} detailPlace={detailPlace} selectedSegment={selectedSegment} itinerary={itinerary} selectedTransport={selectedTransport} setSelectedTransport={setSelectedTransport} handoffProvider={handoffProvider} setHandoffProvider={setHandoffProvider} feedbackDraft={feedbackDraft} setFeedbackDraft={setFeedbackDraft} feedbackSubmitting={feedbackSubmitting} submitFeedback={submitFeedback} copyHandoff={copyHandoff} />
  {toast && <output aria-live="polite" className="fixed inset-x-5 bottom-24 z-[60] mx-auto max-w-[350px] rounded-2xl bg-[#1e2939] px-4 py-3 text-center text-sm text-white shadow-xl">{toast}</output>}
  </main>;
}

function PlannerScreen({ request, setRequest, setDurationHours, openCity, openPreference, onGenerate, onProfile }: { request: PlanRequest; setRequest: Dispatch<SetStateAction<PlanRequest>>; setDurationHours: (value: number) => void; openCity: () => void; openPreference: (key: PreferenceKey) => void; onGenerate: () => void; onProfile: () => void }) {
  const toggleShortcut = (category: PlaceCategory) => setRequest((current) => ({ ...current, interests: current.interests.includes(category) ? current.interests.length > 1 ? current.interests.filter((item) => item !== category) : current.interests : [...current.interests, category] }));
  return <><AppHeader onProfile={onProfile} /><section className="px-5 pb-40 pt-2">
    <button type="button" onClick={openCity} className="mb-5 inline-flex min-h-9 items-center gap-1 rounded-full bg-[#f3f4f6] px-3 text-xs font-medium text-[#4a5565]">New York City <ChevronDown className="size-3.5" /></button>
    <h1 className="text-[22px] font-bold leading-[1.4] tracking-[-0.4px] text-[#101828]">What would you like to do in NYC?</h1>
    <p className="mt-1 text-xs leading-5 text-[#99a1af]">Tell Wayly what matters; plans draw only from published places.</p>
    <div className="mt-5 grid grid-cols-2 gap-2.5">
      <label className="rounded-xl border border-[#e5e7eb] p-3.5"><span className="block text-[10px] text-[#99a1af]">Date</span><span className="mt-1 flex items-center gap-1.5 text-xs font-medium text-[#1e2939]"><CalendarDays className="size-4 text-[#6a7282]" /><input aria-label="Travel date" type="date" value={request.date} onChange={(event) => setRequest((current) => ({ ...current, date: event.target.value }))} className="w-full bg-transparent outline-none" /></span></label>
      <label className="rounded-xl border border-[#e5e7eb] p-3.5"><span className="block text-[10px] text-[#99a1af]">Hours</span><span className="mt-1 flex items-center gap-1.5 text-xs font-medium text-[#1e2939]"><Clock3 className="size-4 text-[#6a7282]" /><input aria-label="Available hours" type="number" min="1" max="24" value={hoursFor(request)} onChange={(event) => setDurationHours(clampNumber(event.target.value, 1, 24, 6))} className="w-12 bg-transparent outline-none" />hours</span></label>
      <div className="rounded-xl border border-[#e5e7eb] p-3.5"><span className="block text-[10px] text-[#99a1af]">Travelers</span><span className="mt-2 flex items-center gap-2.5"><button type="button" aria-label="Remove traveler" onClick={() => setRequest((current) => ({ ...current, partySize: Math.max(1, current.partySize - 1) }))} className="grid size-6 place-items-center rounded-full border border-[#d1d5dc] text-[#6a7282]"><Minus className="size-3" /></button><strong className="min-w-9 text-center text-[13px] font-medium">{request.partySize}</strong><button type="button" aria-label="Add traveler" onClick={() => setRequest((current) => ({ ...current, partySize: Math.min(8, current.partySize + 1) }))} className="grid size-6 place-items-center rounded-full border border-[#d1d5dc] text-[#6a7282]"><Plus className="size-3" /></button></span></div>
      <label className="rounded-xl border border-[#e5e7eb] p-3.5"><span className="block text-[10px] text-[#99a1af]">Total budget</span><span className="mt-1 flex items-center gap-1 text-[13px] font-medium text-[#1e2939]"><WalletCards className="size-4 text-[#6a7282]" />$<input aria-label="Total budget in US dollars" type="number" min="0" max="10000" value={request.totalBudgetUsd} onChange={(event) => setRequest((current) => ({ ...current, totalBudgetUsd: clampNumber(event.target.value, 0, 10_000, current.totalBudgetUsd) }))} className="w-20 bg-transparent outline-none" /></span></label>
    </div>
    <section className="mt-5"><h2 className="flex items-center gap-1.5 text-[13px] font-semibold text-[#1e2939]"><Sparkles className="size-4 text-[#1e5738]" />Tell Wayly what you want to do</h2><div className="mt-2 rounded-2xl border border-[#d0e8d8] bg-[#fafffe] p-3.5"><textarea aria-label="Trip request" value={request.intentText} onChange={(event) => setRequest((current) => ({ ...current, intentText: event.target.value.slice(0, 300) }))} maxLength={300} placeholder="For example: classic architecture, a relaxed museum visit, and views by the water" className="h-16 w-full resize-none bg-transparent text-[13px] leading-5 text-[#1e2939] outline-none placeholder:text-[#c6cbd3]" /><p className="text-right text-[10px] text-[#a3abb7]">{request.intentText.length} / 300</p></div><p className="mt-4 text-[11px] text-[#99a1af]">Or choose quick interests</p><div className="mt-2 flex flex-wrap gap-2">{shortcuts.map((shortcut) => { const active = request.interests.includes(shortcut.category); return <button key={shortcut.label} type="button" onClick={() => toggleShortcut(shortcut.category)} aria-pressed={active} className={`min-h-8 rounded-full px-3.5 text-xs font-medium ${active ? "bg-[#1e5738] text-white" : "bg-[#f3f4f6] text-[#4a5565]"}`}>{shortcut.label}</button>; })}</div></section>
    <section className="mt-5"><h2 className="text-[13px] font-semibold text-[#1e2939]">Your preferences</h2><div className="mt-2 overflow-hidden rounded-2xl border border-[#e5e7eb] bg-white">{(["transport", "walking", "dining", "accessibility"] as const).map((key) => <button key={key} type="button" onClick={() => openPreference(key)} className="flex min-h-14 w-full items-center justify-between border-b border-[#f3f4f6] px-3.5 text-left last:border-0"><span><strong className="block text-xs text-[#4a5565]">{preferences[key].title}</strong><small className="mt-1 block text-[10px] text-[#99a1af]">{preferenceText(request, key)}</small></span><ChevronRight className="size-4 text-[#a3abb7]" /></button>)}</div></section>
    <div className="mt-5 rounded-2xl bg-[#eef8f1] p-3.5"><p className="flex items-center gap-1.5 text-xs font-semibold text-[#1e5738]"><ShieldCheck className="size-4" />Plans use published NYC places</p><p className="mt-1 text-[11px] leading-5 text-[#557462]">Place facts include source links. Transit, availability, and price are estimates and must be checked before travel.</p></div>
  </section><div className="fixed inset-x-0 bottom-0 z-30 border-t border-[#f3f4f6] bg-white/95 px-5 pb-[max(16px,env(safe-area-inset-bottom))] pt-2 backdrop-blur"><div className="mx-auto max-w-[350px]"><Button size="lg" onClick={onGenerate} className="h-12 w-full rounded-2xl bg-[#1e5738] text-sm font-semibold hover:bg-[#18492f]"><Sparkles />Build my NYC plan</Button><p className="mt-2 text-center text-[10px] text-[#99a1af]">Local preview · published NYC catalog</p></div></div></>;
}

function LoadingScreen({ request, onCancel }: { request: PlanRequest; onCancel: () => void }) { return <div className="flex min-h-dvh flex-col bg-[#f8fbf7]"><AppHeader onBack={onCancel} title="Planning" /><div className="flex flex-1 flex-col justify-center px-8 pb-24"><div className="mx-auto grid size-16 place-items-center rounded-3xl bg-[#e8f4eb] text-[#1e5738]"><Compass className="size-8" /></div><h1 className="mt-6 text-center text-xl font-bold text-[#101828]">Building your NYC itinerary</h1><p className="mt-2 text-center text-sm leading-6 text-[#6a7282]">Using published NYC places and your selected constraints.</p><div className="mt-8 space-y-3">{["Checking your constraints", "Selecting published places", "Balancing time and budget"].map((step, index) => <div key={step} className="flex items-center gap-3 rounded-2xl border border-[#e5e7eb] bg-white px-4 py-3"><span className="grid size-6 place-items-center rounded-full bg-[#e9f5eb] text-[#1e5738]">{index === 2 ? <Loader2 className="size-3.5 animate-spin" /> : <Check className="size-3.5" />}</span><span className="text-sm text-[#4a5565]">{step}</span></div>)}</div><div className="mt-8 rounded-2xl bg-white p-4 text-xs text-[#6a7282]"><p className="font-semibold text-[#4a5565]">This trip</p><p className="mt-2">{formatDate(request.date)} · {hoursFor(request)} hours · {request.partySize} travelers · ${request.totalBudgetUsd} total budget</p></div></div><div className="px-5 pb-[max(24px,env(safe-area-inset-bottom))]"><button type="button" onClick={onCancel} className="min-h-11 w-full text-sm text-[#6a7282] underline-offset-4 hover:underline">Cancel and keep inputs</button></div></div>; }

function ItineraryScreen({ itinerary, previousItinerary, plannedPlaces, mode, request, selectedTransport, onBack, onProfile, onOpenDetail, onOpenTransport, onAdjust, onSave, onFeedback, onHome, onProfileNav, onClearChange, showToast }: { itinerary: Itinerary; previousItinerary: Itinerary | null; plannedPlaces: NycPlace[]; mode: PlanMode | null; request: PlanRequest; selectedTransport: Record<string, TransportMode>; onBack: () => void; onProfile: () => void; onOpenDetail: (place: NycPlace) => void; onOpenTransport: (segment: TransportSegment) => void; onAdjust: () => void; onSave: () => void; onFeedback: () => void; onHome: () => void; onProfileNav: () => void; onClearChange: () => void; showToast: (value: string) => void }) {
  const previousIds = new Set(previousItinerary?.stops.map((stop) => stop.placeId) ?? []);
  return <><AppHeader onBack={onBack} onProfile={onProfile} /><section className="px-5 pb-32 pt-1">
    {previousItinerary && <div className="mb-4 rounded-2xl border border-[#cde7d4] bg-[#f1fbf3] p-3.5"><p className="flex items-center gap-1.5 text-sm font-semibold text-[#1e5738]"><Check className="size-4" />Your itinerary was updated</p><p className="mt-1 text-xs leading-5 text-[#557462]">Green labels show changed stops; unaffected stops are retained when possible.</p><button type="button" onClick={onClearChange} className="mt-2 text-xs font-semibold text-[#1e5738]">View the updated route</button></div>}
    <div className="flex items-start justify-between gap-3"><div><p className="text-xs text-[#99a1af]">{formatDate(request.date)} · {hoursFor(request)} hours</p><h1 className="mt-1 text-[22px] font-bold tracking-[-0.4px] text-[#101828]">Your NYC itinerary</h1></div><button type="button" onClick={onAdjust} className="min-h-10 rounded-xl bg-[#eef8f1] px-3 text-xs font-semibold text-[#1e5738]">Adjust plan</button></div>
    <div className="mt-4 grid grid-cols-3 gap-2"><Metric icon={Route} value={`${itinerary.estimatedWalkKm} km`} label="Walking estimate" /><Metric icon={WalletCards} value={`$${itinerary.estimatedTotalSpendUsd.max}`} label="Estimated total" /><Metric icon={MapPin} value={`${itinerary.stops.length}`} label="Published places" /></div>
    <div className="mt-4 overflow-hidden rounded-2xl border border-[#e5e7eb]"><RouteMapClient places={plannedPlaces} /></div><p className="mt-2 text-[10px] leading-4 text-[#99a1af]">Walking uses place coordinates; venue interiors are not covered. Confirm live routes, time, and fares in a map service.</p>
    <div className="mt-5 space-y-0">{itinerary.stops.map((stop, index) => { const place = placeById[stop.placeId]; if (!place) return null; const changed = Boolean(previousItinerary && !previousIds.has(stop.placeId)); return <div key={stop.id} className="relative pl-9"><span className="absolute left-[11px] top-0 h-full border-l border-dashed border-[#d7e5da]" /><span className={`absolute left-0 top-1 grid size-6 place-items-center rounded-full text-[11px] font-semibold ${changed ? "bg-[#1e5738] text-white" : "bg-[#eaf4ec] text-[#1e5738]"}`}>{index + 1}</span><article className={`pb-3 ${changed ? "rounded-2xl bg-[#f4fbf5] px-3 pt-2" : ""}`}><p className="text-[11px] font-medium text-[#6a7282]">{stop.time}</p><button type="button" onClick={() => onOpenDetail(place)} className="mt-1 flex w-full items-start justify-between gap-3 text-left"><span><strong className="block text-sm text-[#1e2939]">{place.name}</strong><span className="mt-1 block text-xs leading-5 text-[#6a7282]">{stop.reason}</span></span><ChevronRight className="mt-1 size-4 shrink-0 text-[#99a1af]" /></button><div className="mt-2 flex flex-wrap gap-1.5"><span className="rounded-full bg-[#f3f4f6] px-2.5 py-1 text-[10px] text-[#4a5565]">Planning allowance ${stop.expectedSpendUsd}</span>{changed && <span className="rounded-full bg-[#dff3e3] px-2.5 py-1 text-[10px] font-medium text-[#1e5738]">Updated</span>}</div></article>{itinerary.transportSegments[index] && <TransportCard segment={itinerary.transportSegments[index]} selectedMode={selectedTransport[itinerary.transportSegments[index].toStopId] ?? itinerary.transportSegments[index].recommendedMode} onOpen={() => onOpenTransport(itinerary.transportSegments[index])} />}</div>; })}</div>
    <div className="mt-5 rounded-2xl bg-[#f8faf8] p-4"><p className="flex items-center gap-1.5 text-xs font-semibold text-[#4a5565]"><ShieldCheck className="size-4 text-[#1e5738]" />Evidence and planning boundary</p><p className="mt-1.5 text-[11px] leading-5 text-[#6a7282]">{itinerary.warnings.join(" ")}</p><p className="mt-2 text-[10px] text-[#99a1af]">{mode === "controlled_fallback" ? "Controlled itinerary" : "Published-place plan"} · {itinerary.dataVersionId}</p></div>
    <div className="mt-5 grid grid-cols-2 gap-2"><Button variant="outline" onClick={onSave} className="h-11 rounded-xl border-[#d7e5da] text-[#1e5738]"><Star />Save plan</Button><Button variant="outline" onClick={() => showToast("Export and sharing are reserved for a later release.")} className="h-11 rounded-xl border-[#e5e7eb] text-[#4a5565]"><Send />Export / Share</Button></div><button type="button" onClick={onFeedback} className="mt-3 min-h-11 w-full rounded-xl bg-[#1e5738] px-4 text-sm font-semibold text-white">Rate this itinerary</button>
  </section><BottomNav active="home" onHome={onHome} onProfile={onProfileNav} /></>;
}

function Metric({ icon: Icon, value, label }: { icon: typeof Route; value: string; label: string }) { return <div className="rounded-xl bg-[#f8f9f8] p-3"><Icon className="size-4 text-[#1e5738]" /><strong className="mt-2 block text-sm text-[#1e2939]">{value}</strong><small className="mt-0.5 block text-[10px] leading-4 text-[#99a1af]">{label}</small></div>; }
function TransportCard({ segment, selectedMode, onOpen }: { segment: TransportSegment; selectedMode: TransportMode; onOpen: () => void }) { return <div className="mb-3 rounded-xl border border-[#eef0ec] bg-[#fbfcfb] px-3 py-2.5"><div className="flex items-center justify-between gap-2"><span className="flex items-center gap-2 text-[11px] font-medium text-[#4a5565]"><TransportIcon mode={selectedMode} className="size-3.5 text-[#1e5738]" />{transportLabel(selectedMode)} · {segment.estimatedMinutes.min}–{segment.estimatedMinutes.max} min</span><button type="button" onClick={onOpen} className="min-h-8 rounded-lg px-2 text-[11px] font-semibold text-[#1e5738] hover:bg-[#eef8f1]">Options</button></div><p className="mt-1 text-[10px] leading-4 text-[#99a1af]">{segment.uncertaintyNotice}</p></div>; }

function AdjustmentScreen({ itinerary, request, action, targetStopId, candidateId, budget, onBack, onAction, onTarget, onCandidate, onBudget, onSubmit }: { itinerary: Itinerary; request: PlanRequest; action: AdjustmentAction; targetStopId: string | null; candidateId: string | null; budget: number; onBack: () => void; onAction: (value: AdjustmentAction) => void; onTarget: (value: string) => void; onCandidate: (value: string) => void; onBudget: (value: number) => void; onSubmit: () => void }) {
  const target = itinerary.stops.find((stop) => stop.id === targetStopId); const candidates = suggestReplacements(itinerary, target?.id ?? null, request);
  return <div className="min-h-dvh bg-white"><AppHeader onBack={onBack} title="Adjust itinerary" /><section className="px-5 pb-32"><h1 className="text-[22px] font-bold tracking-[-0.4px] text-[#101828]">Make this plan fit better</h1><p className="mt-1 text-xs leading-5 text-[#99a1af]">Only change what is necessary; Wayly will preserve other stops when possible.</p><div className="mt-5 grid grid-cols-3 rounded-xl bg-[#f3f4f6] p-1">{(["replace", "shorten", "budget"] as const).map((item) => <button key={item} type="button" onClick={() => onAction(item)} className={`min-h-9 rounded-lg text-xs font-semibold ${action === item ? "bg-white text-[#1e5738] shadow-sm" : "text-[#6a7282]"}`}>{item === "replace" ? "Replace" : item === "shorten" ? "Shorten" : "Budget"}</button>)}</div>
    {action === "replace" && <div className="mt-5"><p className="text-xs font-semibold text-[#4a5565]">Which stop should change?</p><select aria-label="Select a stop to replace" value={target?.id} onChange={(event) => onTarget(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#e5e7eb] bg-white px-3 text-sm outline-none focus:border-[#1e5738]">{itinerary.stops.map((stop) => <option key={stop.id} value={stop.id}>{stop.name}</option>)}</select><p className="mt-4 text-xs font-semibold text-[#4a5565]">Published candidates to consider</p><div className="mt-2 space-y-2">{candidates.map((candidate) => <button key={candidate.id} type="button" onClick={() => onCandidate(candidate.id)} className={`flex w-full overflow-hidden rounded-2xl border text-left ${candidateId === candidate.id ? "border-[#1e5738] bg-[#f2faf4]" : "border-[#e5e7eb] bg-white"}`}><img src={candidate.imageUrl} alt="" className="h-[82px] w-24 shrink-0 object-cover" referrerPolicy="no-referrer" /><span className="flex min-w-0 flex-1 items-center justify-between gap-2 p-3"><span><strong className="block text-sm text-[#1e2939]">{candidate.name}</strong><small className="mt-1 block text-[11px] leading-4 text-[#6a7282]">Published source · planning allowance ${candidate.planningAllowanceUsd * request.partySize}</small></span>{candidateId === candidate.id && <Check className="size-4 shrink-0 text-[#1e5738]" />}</span></button>)}</div><p className="mt-2 text-[10px] leading-4 text-[#99a1af]">Candidate cards are a preview; the planner validates the new route against the same published catalog.</p></div>}
    {action === "shorten" && <div className="mt-5 rounded-2xl bg-[#f8f9f8] p-4 text-sm text-[#4a5565]"><strong className="block">Shorten the day</strong><p className="mt-2 text-xs leading-5">Wayly will reduce available time by two hours and choose fewer stops if needed.</p></div>}
    {action === "budget" && <div className="mt-5"><p className="text-xs font-semibold text-[#4a5565]">New total budget</p><div className="mt-2 flex h-14 items-center rounded-2xl border border-[#d0e8d8] bg-[#fafffe] px-4"><WalletCards className="mr-2 size-5 text-[#1e5738]" /><span className="mr-1 text-sm">$</span><input aria-label="New total budget in US dollars" type="number" min="0" max="10000" value={budget} onChange={(event) => onBudget(clampNumber(event.target.value, 0, 10_000, budget))} className="w-full bg-transparent text-lg font-semibold outline-none" /></div><p className="mt-2 text-xs leading-5 text-[#99a1af]">Previous budget ${request.totalBudgetUsd}. Place allowances and static transport estimates will be checked against the trip total.</p></div>}
    <div className="mt-6 rounded-2xl border border-[#eef0ec] p-4"><p className="text-xs font-semibold text-[#4a5565]">Change preview</p><p className="mt-2 text-sm text-[#1e2939]">{action === "replace" ? `Try replacing ${target?.name ?? "the selected stop"}` : action === "shorten" ? "Reduce stops and shorten the overall pace" : `Total budget $${request.totalBudgetUsd} → $${budget}`}</p><p className="mt-1 text-[11px] leading-5 text-[#99a1af]">After submission, Wayly shows the resulting route, budget, and transit changes.</p></div>
  </section><div className="fixed inset-x-0 bottom-0 z-30 border-t border-[#f3f4f6] bg-white/95 px-5 pb-[max(16px,env(safe-area-inset-bottom))] pt-2 backdrop-blur"><div className="mx-auto max-w-[350px]"><Button size="lg" onClick={onSubmit} className="h-12 w-full rounded-2xl bg-[#1e5738] hover:bg-[#18492f]"><RefreshCw />Update itinerary</Button></div></div></div>;
}

function ConstraintScreen({ message, request, onEdit, onRelax }: { message: string; request: PlanRequest; onEdit: () => void; onRelax: () => void }) { return <div className="flex min-h-dvh flex-col bg-[#fffdf8]"><AppHeader onBack={onEdit} title="Adjust constraints" /><div className="flex flex-1 flex-col justify-center px-6 pb-20"><div className="grid size-14 place-items-center rounded-2xl bg-[#fff0d9] text-[#b45309]"><AlertTriangle className="size-7" /></div><h1 className="mt-5 text-xl font-bold text-[#101828]">These constraints conflict</h1><p className="mt-2 text-sm leading-6 text-[#6a7282]">{message}</p><div className="mt-6 rounded-2xl bg-white p-4"><p className="text-xs font-semibold text-[#4a5565]">Practical next steps</p><ul className="mt-3 space-y-3 text-xs leading-5 text-[#6a7282]"><li>· Increase the total budget or reduce the party size</li><li>· Reduce the number of places within the available time</li><li>· Relax preferences where current source evidence is limited</li></ul><p className="mt-3 text-[10px] text-[#99a1af]">Current: {hoursFor(request)} hours · ${request.totalBudgetUsd} total budget</p></div></div><div className="space-y-2 px-5 pb-[max(24px,env(safe-area-inset-bottom))]"><Button size="lg" onClick={onRelax} className="h-12 w-full rounded-2xl bg-[#1e5738] hover:bg-[#18492f]">Apply a relaxed suggestion</Button><Button variant="ghost" onClick={onEdit} className="h-11 w-full rounded-xl text-[#6a7282]">Edit inputs</Button></div></div>; }
function ErrorScreen({ message, onRetry, onEdit }: { message: string; onRetry: () => void; onEdit: () => void }) { return <div className="flex min-h-dvh flex-col bg-[#fffdfd]"><AppHeader onBack={onEdit} title="Something went wrong" /><div className="flex flex-1 flex-col justify-center px-6 pb-20"><div className="grid size-14 place-items-center rounded-2xl bg-[#fff0f0] text-[#b42318]"><CircleAlert className="size-7" /></div><h1 className="mt-5 text-xl font-bold text-[#101828]">Planning is unavailable</h1><p className="mt-2 text-sm leading-6 text-[#6a7282]">{message}</p></div><div className="space-y-2 px-5 pb-[max(24px,env(safe-area-inset-bottom))]"><Button size="lg" onClick={onRetry} className="h-12 w-full rounded-2xl bg-[#1e5738] hover:bg-[#18492f]">Try again</Button><Button variant="ghost" onClick={onEdit} className="h-11 w-full rounded-xl text-[#6a7282]">Edit inputs</Button></div></div>; }
function ProfileScreen({ itinerary, onBack, onSave, onHome, onProfile }: { itinerary: Itinerary | null; onBack: () => void; onSave: () => void; onHome: () => void; onProfile: () => void }) { return <><AppHeader onBack={onBack} title="Profile" /><section className="px-5 pb-32 pt-3"><div className="rounded-3xl bg-[#f2faf4] p-5"><div className="grid size-11 place-items-center rounded-2xl bg-white text-[#1e5738]"><UserRound className="size-5" /></div><h1 className="mt-4 text-xl font-bold text-[#101828]">Save your NYC plans</h1><p className="mt-2 text-xs leading-5 text-[#557462]">Sign-in remains a preview. No account or private data is created from this page.</p><Button onClick={onSave} className="mt-4 h-11 rounded-xl bg-[#1e5738] hover:bg-[#18492f]">Learn about saving plans</Button></div><div className="mt-5 rounded-2xl border border-[#e5e7eb] p-4"><p className="text-xs font-semibold text-[#4a5565]">Current preview</p><p className="mt-2 text-sm text-[#1e2939]">{itinerary ? itinerary.title : "No itinerary generated yet"}</p><p className="mt-1 text-[11px] leading-5 text-[#99a1af]">The app does not persist this preview across sessions.</p></div></section><BottomNav active="profile" onHome={onHome} onProfile={onProfile} /></>; }
function ScoreGroup({ label, value, onChange }: { label: string; value: number; onChange: (value: number) => void }) { return <div><p className="text-xs font-semibold text-[#4a5565]">{label}</p><div className="mt-2 flex gap-1">{[1, 2, 3, 4, 5].map((score) => <button key={score} type="button" onClick={() => onChange(score)} aria-label={`${label}: ${score} out of 5`} className={`grid size-9 place-items-center rounded-lg ${score <= value ? "text-[#e4a72d]" : "text-[#d9dde3]"}`}><Star className="size-6" fill="currentColor" /></button>)}</div></div>; }

function OverlaySheets({ sheet, setSheet, request, setRequest, preferenceKey, detailPlace, selectedSegment, itinerary, selectedTransport, setSelectedTransport, handoffProvider, setHandoffProvider, feedbackDraft, setFeedbackDraft, feedbackSubmitting, submitFeedback, copyHandoff }: { sheet: SheetName; setSheet: (value: SheetName) => void; request: PlanRequest; setRequest: Dispatch<SetStateAction<PlanRequest>>; preferenceKey: PreferenceKey; detailPlace: NycPlace | null; selectedSegment: TransportSegment | null; itinerary: Itinerary | null; selectedTransport: Record<string, TransportMode>; setSelectedTransport: Dispatch<SetStateAction<Record<string, TransportMode>>>; handoffProvider: string | null; setHandoffProvider: (value: string | null) => void; feedbackDraft: { satisfaction: number; trust: number; issueType: string; note: string }; setFeedbackDraft: Dispatch<SetStateAction<{ satisfaction: number; trust: number; issueType: string; note: string }>>; feedbackSubmitting: boolean; submitFeedback: () => void; copyHandoff: () => Promise<void> }) {
  const activeTransport = selectedSegment ? selectedTransport[selectedSegment.toStopId] ?? selectedSegment.recommendedMode : "walk";
  const from = itinerary?.stops.find((stop) => stop.id === selectedSegment?.fromStopId)?.name ?? "Start"; const to = itinerary?.stops.find((stop) => stop.id === selectedSegment?.toStopId)?.name ?? "Destination";
  const preference = preferences[preferenceKey]; const currentValue = preferenceKey === "accessibility" ? String(request.accessibility) : String(request[preferenceKey === "transport" ? "transportPreference" : preferenceKey === "walking" ? "walkingPreference" : "dining"]);
  return <>
    <Sheet open={sheet === "city"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="max-h-[80dvh] rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>Choose city</SheetTitle><SheetDescription>Only New York City has a published catalog in this preview.</SheetDescription></SheetHeader><div className="px-5 pb-5"><button type="button" onClick={() => setSheet(null)} className="flex min-h-14 w-full items-center justify-between rounded-2xl border border-[#1e5738] bg-[#f2faf4] px-4 text-left"><span><strong className="block text-sm text-[#1e5738]">New York City</strong><small className="mt-1 block text-[11px] text-[#557462]">Supported · published source catalog</small></span><Check className="size-5 text-[#1e5738]" /></button>{["Boston", "Philadelphia", "Chicago"].map((city) => <div key={city} className="mt-2 flex min-h-14 items-center justify-between rounded-2xl bg-[#f8f9f8] px-4 text-sm text-[#a3abb7]"><span>{city}</span><small>Coming later</small></div>)}</div></SheetContent></Sheet>
    <Sheet open={sheet === "preferences"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>{preference.title}</SheetTitle><SheetDescription>Your choice is used as a planning constraint.</SheetDescription></SheetHeader><div className="space-y-2 px-5 pb-5">{preference.options.map((option) => <button key={option.value} type="button" onClick={() => { setRequest((current) => preferenceKey === "accessibility" ? { ...current, accessibility: option.value === "true" } : preferenceKey === "transport" ? { ...current, transportPreference: option.value as PlanRequest["transportPreference"] } : preferenceKey === "walking" ? { ...current, walkingPreference: option.value as PlanRequest["walkingPreference"] } : { ...current, dining: option.value as PlanRequest["dining"] }); setSheet(null); }} className={`flex min-h-12 w-full items-center justify-between rounded-xl border px-3.5 text-left ${currentValue === option.value ? "border-[#1e5738] bg-[#f2faf4] text-[#1e5738]" : "border-[#e5e7eb] text-[#4a5565]"}`}><span><strong className="block text-sm font-medium">{option.label}</strong>{option.note && <small className="mt-1 block max-w-[260px] text-[10px] leading-4 text-[#99a1af]">{option.note}</small>}</span>{currentValue === option.value && <Check className="size-4" />}</button>)}</div></SheetContent></Sheet>
    <Sheet open={sheet === "detail"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="max-h-[85dvh] rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>{detailPlace?.name ?? "Place details"}</SheetTitle><SheetDescription>{detailPlace?.interests.join(" · ")}</SheetDescription></SheetHeader>{detailPlace && <div className="space-y-4 px-5 pb-6 text-sm"><img src={detailPlace.imageUrl} alt={`${detailPlace.name} preview`} className="h-44 w-full rounded-2xl object-cover" referrerPolicy="no-referrer" /><p className="leading-6 text-[#6a7282]">{detailPlace.neighborhood}. {detailPlace.accessNote}</p><div className="rounded-2xl bg-[#f8f9f8] p-3.5"><p className="text-xs font-semibold text-[#4a5565]">Published source</p><p className="mt-1 text-xs leading-5 text-[#6a7282]">{detailPlace.sourceName} · reviewed {detailPlace.reviewedOn}</p><a href={detailPlace.sourceUrl} target="_blank" rel="noreferrer" className="mt-2 inline-flex min-h-9 items-center gap-1 text-xs font-semibold text-[#1e5738]"><ExternalLink className="size-3.5" />Open source</a></div><div className="rounded-2xl border border-[#eef0ec] p-3.5 text-xs leading-5 text-[#6a7282]"><strong className="text-[#4a5565]">Budget note: </strong>{detailPlace.priceNote}<a href={detailPlace.imageCreditUrl} target="_blank" rel="noreferrer" className="mt-2 block text-[#1e5738]">View image credit</a></div><div className="rounded-2xl border border-[#f2deb7] bg-[#fffaf0] p-3.5 text-xs leading-5 text-[#8a5a16]"><AlertTriangle className="mr-1 inline size-3.5" />Hours, reservations, tickets, and on-site conditions are not live. Check the source on the day of travel.</div></div>}</SheetContent></Sheet>
    <Sheet open={sheet === "transport"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="max-h-[86dvh] rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>Choose a travel mode</SheetTitle><SheetDescription>{from} → {to} · planning estimates only</SheetDescription></SheetHeader>{selectedSegment && <div className="space-y-2 px-5 pb-6">{(["walk", "public_transit", "taxi"] as const).map((item) => { const chosen = activeTransport === item; const amount = item === "walk" ? "$0" : item === "public_transit" ? `$${selectedSegment.estimatedCostUsd?.min ?? 3}–$${selectedSegment.estimatedCostUsd?.max ?? 6}` : "Confirm in your taxi app"; return <button key={item} type="button" onClick={() => setSelectedTransport((current) => ({ ...current, [selectedSegment.toStopId]: item }))} className={`flex w-full items-center gap-3 rounded-2xl border p-3.5 text-left ${chosen ? "border-[#1e5738] bg-[#f2faf4]" : "border-[#e5e7eb]"}`}><span className="grid size-10 place-items-center rounded-xl bg-white text-[#1e5738]"><TransportIcon mode={item} className="size-5" /></span><span className="flex-1"><strong className="block text-sm text-[#1e2939]">{transportLabel(item)}</strong><small className="mt-1 block text-[11px] text-[#6a7282]">Estimated {selectedSegment.estimatedMinutes.min}–{selectedSegment.estimatedMinutes.max} min · {amount}</small></span>{chosen && <Check className="size-4 text-[#1e5738]" />}</button>; })}<Button size="lg" onClick={() => { setHandoffProvider(null); setSheet("handoff"); }} className="mt-3 h-12 w-full rounded-2xl bg-[#1e5738] hover:bg-[#18492f]"><Navigation />Continue in maps</Button><p className="text-center text-[10px] leading-4 text-[#99a1af]">A map provider owns live routes, fares, and execution; Wayly does not initiate navigation, rides, or payment.</p></div>}</SheetContent></Sheet>
    <Sheet open={sheet === "handoff"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>Continue in maps</SheetTitle><SheetDescription>{from} → {to}</SheetDescription></SheetHeader><div className="px-5 pb-6">{handoffProvider ? <div><div className="rounded-2xl bg-[#f6fbf7] p-4"><p className="text-sm font-semibold text-[#1e5738]">{handoffProvider}</p><p className="mt-2 text-xs leading-5 text-[#557462]">Wayly would hand off the endpoints and travel mode. The map provider owns live routing, price, and execution.</p></div><p className="mt-4 text-xs leading-5 text-[#6a7282]">This local preview does not open a deep link. Copy the endpoints and search in your preferred map.</p><Button size="lg" onClick={() => void copyHandoff()} className="mt-4 h-12 w-full rounded-2xl bg-[#1e5738] hover:bg-[#18492f]"><Copy />Copy route endpoints</Button></div> : <div className="space-y-2">{["Google Maps", "Apple Maps", "Citymapper"].map((provider) => <button key={provider} type="button" onClick={() => setHandoffProvider(provider)} className="flex min-h-13 w-full items-center justify-between rounded-2xl border border-[#e5e7eb] px-4 text-left"><span><strong className="block text-sm text-[#1e2939]">{provider}</strong><small className="mt-1 block text-[11px] text-[#99a1af]">Preview only · no external launch</small></span><ChevronRight className="size-4 text-[#99a1af]" /></button>)}</div>}</div></SheetContent></Sheet>
    <Sheet open={sheet === "feedback"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="max-h-[92dvh] rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>Was this itinerary helpful?</SheetTitle><SheetDescription>Feedback is associated with this preview and its data version.</SheetDescription></SheetHeader><div className="space-y-5 px-5 pb-6"><ScoreGroup label="Overall satisfaction" value={feedbackDraft.satisfaction} onChange={(value) => setFeedbackDraft((current) => ({ ...current, satisfaction: value }))} /><ScoreGroup label="How much do you trust this recommendation?" value={feedbackDraft.trust} onChange={(value) => setFeedbackDraft((current) => ({ ...current, trust: value }))} /><div className="border-t border-[#f3f4f6] pt-4"><p className="text-xs font-semibold text-[#4a5565]">If something was wrong, what was it?</p><div className="mt-2 flex flex-wrap gap-2">{[{ value: "fit", label: "Not my interests" }, { value: "route", label: "Route does not fit" }, { value: "budget", label: "Budget estimate" }, { value: "walking", label: "Too much walking" }, { value: "data", label: "Place information" }, { value: "other", label: "Other" }].map((item) => <button key={item.value} type="button" onClick={() => setFeedbackDraft((current) => ({ ...current, issueType: current.issueType === item.value ? "" : item.value }))} className={`min-h-8 rounded-full border px-3 text-[11px] ${feedbackDraft.issueType === item.value ? "border-[#1e5738] bg-[#f2faf4] text-[#1e5738]" : "border-[#e5e7eb] text-[#4a5565]"}`}>{item.label}</button>)}</div></div><label className="block border-t border-[#f3f4f6] pt-4"><span className="text-xs font-semibold text-[#4a5565]">Anything else to share?</span><textarea aria-label="Feedback details" value={feedbackDraft.note} maxLength={500} onChange={(event) => setFeedbackDraft((current) => ({ ...current, note: event.target.value }))} placeholder="For example: I would like a shorter walk or more local food options." className="mt-2 h-20 w-full resize-none rounded-xl border border-[#e5e7eb] p-3 text-xs leading-5 outline-none placeholder:text-[#c6cbd3] focus:border-[#1e5738]" /></label><Button size="lg" disabled={feedbackSubmitting} onClick={submitFeedback} className="h-12 w-full rounded-2xl bg-[#1e5738] hover:bg-[#18492f]">{feedbackSubmitting ? <Loader2 className="animate-spin" /> : <Send />}{feedbackSubmitting ? "Submitting…" : "Submit feedback"}</Button><SheetClose render={<button type="button" className="min-h-9 w-full text-xs text-[#99a1af]">Skip for now</button>} /></div></SheetContent></Sheet>
    <Sheet open={sheet === "auth"} onOpenChange={(open) => !open && setSheet(null)}><SheetContent side="bottom" className="rounded-t-3xl bg-white"><SheetHeader className="px-5 pt-7"><SheetTitle>Save itinerary</SheetTitle><SheetDescription>Account features remain an interface preview; sign-in is not simulated here.</SheetDescription></SheetHeader><div className="px-5 pb-6"><div className="rounded-2xl bg-[#f6fbf7] p-4"><p className="flex items-center gap-1.5 text-sm font-semibold text-[#1e5738]"><UserRound className="size-4" />Identity service pending</p><p className="mt-2 text-xs leading-5 text-[#557462]">After sign-in, privacy, data-storage, and session controls are implemented, this area can save real itineraries and profile preferences. This preview creates no account and writes no private data.</p></div><Link href="/login" className="mt-4 flex h-12 items-center justify-center rounded-2xl bg-[#1e5738] text-sm font-semibold text-white">Go to sign in</Link><SheetClose render={<button type="button" aria-label="Close save itinerary note" className="mt-2 min-h-11 w-full text-sm text-[#6a7282]" />}>Got it</SheetClose></div></SheetContent></Sheet>
  </>;
}
